def backup_current_app() -> Path:
    """Create a complete backup of the current RC11 Appeals application."""
    BACKUP_ROOT.mkdir(parents=True, exist_ok=True)
    backup_dir = BACKUP_ROOT / datetime.now().strftime("%Y%m%d_%H%M%S")
    if APP_DIR.exists():
        shutil.copytree(APP_DIR, backup_dir)
    else:
        backup_dir.mkdir(parents=True, exist_ok=True)
    return backup_dir


def remove_current_app() -> None:
    """Remove the current RC11 Appeals tree after backup."""
    if APP_DIR.exists():
        shutil.rmtree(APP_DIR)


def write_files() -> None:
    """Create the complete RC11 Appeals application tree."""
    for relative_path, content in FILES.items():
        destination = BASE_DIR / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(
            content.rstrip() + "\n",
            encoding="utf-8",
        )


def remove_python_caches() -> None:
    """Remove Python bytecode caches from the rebuilt application."""
    for cache_dir in APP_DIR.rglob("__pycache__"):
        if cache_dir.is_dir():
            shutil.rmtree(cache_dir)


def verify_no_collisions() -> None:
    """Verify that no module/package collisions remain."""
    names = (
        "models",
        "events",
        "permissions",
        "policies",
        "selectors",
        "services",
        "workflows",
    )
    collisions = [name for name in names if (APP_DIR / f"{name}.py").exists()]
    if collisions:
        raise RuntimeError("Module/package collisions remain: " + ", ".join(collisions))


def compile_python() -> None:
    """Compile every rebuilt RC11 Appeals Python source file."""
    import py_compile

    failures = []
    for source in APP_DIR.rglob("*.py"):
        try:
            py_compile.compile(
                str(source),
                doraise=True,
            )
        except py_compile.PyCompileError as exc:
            failures.append(f"{source}: {exc}")

    if failures:
        raise RuntimeError("PY_COMPILE failed:\n" + "\n".join(failures))


def verify_required_files() -> None:
    """Verify all required bounded-context files exist."""
    required = (
        "models/appeal.py",
        "events/appeal.py",
        "permissions/__init__.py",
        "policies/__init__.py",
        "selectors/__init__.py",
        "services/__init__.py",
        "workflows/__init__.py",
        "api/serializers/__init__.py",
        "api/views/__init__.py",
        "api/urls.py",
        "urls.py",
    )
    missing = [
        str(APP_DIR / relative_path)
        for relative_path in required
        if not (APP_DIR / relative_path).exists()
    ]
    if missing:
        raise RuntimeError("Required RC11 files are missing:\n" + "\n".join(missing))


def main() -> int:
    """Execute the complete RC11 Appeals rebuild."""
    print("DatavionAI Revenue Cycle RC11 Appeals Complete Rebuild Installer v2.0.0")
    print("=" * 78)

    backup_dir = backup_current_app()
    print(f"BACKUP CREATED: {backup_dir.relative_to(BASE_DIR)}")

    remove_current_app()
    write_files()
    remove_python_caches()
    verify_required_files()
    verify_no_collisions()
    print("COMPLETE TREE RECREATED: PASS")
    print("PACKAGE COLLISIONS: NONE")

    compile_python()
    print("PY_COMPILE: PASS")
    print(f"FILES WRITTEN: {len(FILES)}")
    print("MIGRATIONS NOT GENERATED")
    print("DATABASE NOT MODIFIED")
    print("LEGACY PATIENT MODULE NOT MODIFIED")
    print("RC11 APPEALS COMPLETE REBUILD: PASS")

    return 0


if __name__ == "__main__":
    sys.exit(main())
